/* TMT Dealer Intelligence — sample store operations, based on supplied VC PDF and HTML. */
const $=(q,root=document)=>root.querySelector(q), $$=(q,root=document)=>[...root.querySelectorAll(q)];
const ICONS={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',orbit:'<circle cx="12" cy="12" r="3"/><ellipse cx="12" cy="12" rx="10" ry="5" transform="rotate(-40 12 12)"/><path d="M9 2c5-1 10 4 11 9M4 14c1 5 6 8 10 8"/>',layers:'<path d="m3 7 9-5 9 5-9 5-9-5Zm0 5 9 5 9-5M3 17l9 5 9-5"/>',matrix:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 3v18M15 3v18M3 9h18M3 15h18"/>',bolt:'<path d="m13 2-9 12h7l-1 8L21 9h-8l1-7Z"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',motion:'<path d="M3 7h10M3 12h15M3 17h10M17 5l4 2-4 2m4 6-4 2 4 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="M4 17 11 10l4 4 6-9m-6 0h6v6"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a4 4 0 0 1 0 8m2 3a5 5 0 0 1 3 6"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18m-12 4h3m3 0h3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${ICONS[n]||ICONS.spark}</svg>`;}
function hydrate(root=document){$$('[data-icon]',root).forEach(el=>el.innerHTML=icon(el.dataset.icon));}
const gold='#dbc19a',ice='#9ad7d4',dim='#596871',orange='#dd9b75';

function fmt(n,d){return n.toLocaleString('en-US',{minimumFractionDigits:d??(n%1?1:0),maximumFractionDigits:d??(n<1?2:1)})}

function signed(n,d=1){return `${n>=0?'+':'−'}${Math.abs(n).toFixed(d)}`}

function escapeHtml(v){return String(v).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}

function tag(label,color=''){return `<span class="pill ${color}"><i></i>${label}</span>`}

function metric(label,value,unit,delta,compare,id,view){return `<button class="metric" data-${view?'view':'detail'}="${view||id}" aria-label="${label} details"><div class="metric-head"><span>${label}</span>${icon('up')}</div><div class="metric-value"><span class="count-up" data-number="${value}">${fmt(value)}</span><small>${unit}</small></div><div class="metric-foot"><b>${delta}</b>${compare}</div><div class="metric-spark"><canvas id="spark-${id}" aria-hidden="true"></canvas></div></button>`}

function chartDefaults(){Chart.defaults.color='#7e8b93';Chart.defaults.font.family="'SFMono-Regular',Consolas,monospace";Chart.defaults.font.size=8;Chart.defaults.plugins.legend.display=false;Chart.defaults.plugins.tooltip.backgroundColor='#202729';Chart.defaults.plugins.tooltip.titleColor=gold;Chart.defaults.plugins.tooltip.bodyColor='#e7edeb';Chart.defaults.plugins.tooltip.borderColor='#dbc19a44';Chart.defaults.plugins.tooltip.borderWidth=1;Chart.defaults.plugins.tooltip.padding=12;Chart.defaults.animation.duration=state.motion?1000:0;}

function lineChart(id,labels,datasets,extra={}){const canvas=$('#'+id);if(!canvas)return;const ctx=canvas.getContext('2d');const fill=ctx.createLinearGradient(0,0,0,250);fill.addColorStop(0,'#dbc19a23');fill.addColorStop(1,'#dbc19a00');const c=new Chart(ctx,{type:'line',data:{labels,datasets:datasets.map((ds,i)=>({borderWidth:1.7,pointRadius:0,pointHoverRadius:4,tension:.38,fill:i===0,backgroundColor:fill,...ds}))},options:{responsive:true,maintainAspectRatio:false,animation:state.motion?{duration:1000,easing:'easeOutQuart'}:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:false},tooltip:{callbacks:{label:ctx=>`${ctx.dataset.label}: ${Number(ctx.parsed.y).toFixed(1)}%`}}},scales:{x:{grid:{display:false},border:{display:false},ticks:{maxTicksLimit:5,color:'#647078',font:{size:7},maxRotation:0}},y:{border:{display:false},grid:{color:'#ffffff07',drawTicks:false},ticks:{maxTicksLimit:4,padding:9,font:{size:7},callback:v=>v+'%'}}},...extra}});charts.push(c);return c}

function spark(id,data,color=gold){const el=$('#spark-'+id);if(!el)return;const c=new Chart(el,{type:'line',data:{labels:data.map((_,i)=>i),datasets:[{data,borderColor:color,borderWidth:1.2,pointRadius:0,tension:.4,fill:false}]},options:{responsive:true,maintainAspectRatio:false,animation:state.motion?{duration:1400}:false,events:[],plugins:{legend:{display:false},tooltip:{enabled:false}},scales:{x:{display:false},y:{display:false}}}});charts.push(c)}

function animateNumbers(){if(!state.motion)return;$$('.count-up').forEach(el=>{const target=+el.dataset.number;let start;let raf;const decimals=target%1?1:0;function draw(t){start??=t;const p=Math.min(1,(t-start)/1100),e=1-Math.pow(1-p,4);el.textContent=fmt(target*(.63+.37*e),decimals);if(p<1)raf=requestAnimationFrame(draw)}raf=requestAnimationFrame(draw);animationHandles.push(()=>cancelAnimationFrame(raf));})}

function openDrawer(html){previousFocus=document.activeElement;$('#drawerContent').innerHTML=html;$('#drawerBackdrop').hidden=false;$('#detailDrawer').hidden=false;document.body.style.overflow='hidden';$('.shell').inert=true;$('.sidebar').inert=true;$('#tourBar').inert=true;hydrate($('#detailDrawer'));$('#drawerClose').focus();if(state.tour)pauseTour(true)}

function closeDrawer(){if(drawerChart){drawerChart.destroy();drawerChart=null}$('#drawerBackdrop').hidden=true;$('#detailDrawer').hidden=true;document.body.style.overflow='';$('.shell').inert=false;$('.sidebar').inert=false;$('#tourBar').inert=false;if(previousFocus?.isConnected)previousFocus.focus()}

function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}

function toggleMotion(){state.motion=!state.motion;document.body.classList.toggle('motion-off',!state.motion);$('#motionButton').setAttribute('aria-label',state.motion?'Pause motion':'Resume motion');Chart.defaults.animation.duration=state.motion?1000:0;charts.forEach(c=>{c.options.animation=state.motion?{duration:800}:false;c.update('none')});toast(state.motion?'Motion resumed':'Motion paused')}

function actionCard(a){return `<article class="action-card ${a.status==='done'?'done-card':''}"><div class="action-priority"><span>${escapeHtml(a.status==='done'?'COMPLETED':a.priority)}</span><span>${escapeHtml(a.group)}</span></div><h3>${escapeHtml(a.title)}</h3><p>${escapeHtml(a.description)}</p><div class="action-impact">↗ ${escapeHtml(a.impact)}</div><div class="action-meta"><span class="avatar">${escapeHtml(a.owner)}</span><span>${escapeHtml(a.ownerName)}</span><span>${escapeHtml(a.due)}</span></div><button class="action-move" data-move="${escapeHtml(a.id)}"><span>${a.status==='todo'?'Start action':a.status==='doing'?'Mark complete':'Reopen action'}</span>${icon(a.status==='doing'?'check':'arrow')}</button></article>`}

function makeNetwork(canvas,mode){if(!canvas)return;const ctx=canvas.getContext('2d');let width=1,height=1,raf,stopped=false,hover={x:0,y:0},last=0,phase=0;const points=Array.from({length:mode==='core'?220:154},(_,i)=>{const y=1-(i/(mode==='core'?219:153))*2,r=Math.sqrt(1-y*y),a=i*2.3999632297;return {x:Math.cos(a)*r,y,z:Math.sin(a)*r}});const links=[];for(let i=0;i<points.length;i++){for(let j=i+1;j<points.length;j++){const a=points[i],b=points[j],d=Math.hypot(a.x-b.x,a.y-b.y,a.z-b.z);if(d<.29)links.push([i,j])}}
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw(last||0)}
function draw(t){if(stopped)return;ctx.clearRect(0,0,width,height);const core=mode==='core',cx=width*.5,cy=height*(core?.54:.48),radius=Math.min(width*(core?.23:.27),height*(core?.29:.47));const angle=phase+hover.x*.1,tilt=.28+hover.y*.1;const cs=Math.cos(angle),sn=Math.sin(angle),ct=Math.cos(tilt),st=Math.sin(tilt);const projected=points.map(p=>{const x=p.x*cs+p.z*sn,z=p.z*cs-p.x*sn,y=p.y*ct-z*st,z2=p.y*st+z*ct;return {x:cx+x*radius*(core?1:1.42),y:cy+y*radius*.85,z:z2}});
const halo=ctx.createRadialGradient(cx,cy,5,cx,cy,radius*1.8);halo.addColorStop(0,core?'#c3a57613':'#9ad7d40e');halo.addColorStop(1,'#00000000');ctx.fillStyle=halo;ctx.fillRect(0,0,width,height);
ctx.strokeStyle='#dbc19a13';ctx.lineWidth=.65;for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(cx,cy,radius*(1.13+i*.14)*(core?1:1.2),radius*(.35+i*.12),-.37+i*.67,0,Math.PI*2);ctx.stroke();}
for(const [i,j] of links){const a=projected[i],b=projected[j],alpha=(a.z+b.z+2)/4*.2+.025;ctx.strokeStyle=`rgba(${core?'219,193,154':'154,215,212'},${alpha})`;ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}
projected.forEach((p,i)=>{let alpha=(p.z+1)/2*.7+.09;ctx.fillStyle=`rgba(${i%6===0?'154,215,212':'219,193,154'},${alpha})`;ctx.beginPath();ctx.arc(p.x,p.y,p.z>.5?1.2:.75,0,Math.PI*2);ctx.fill();if(i%29===0&&p.z>.2){ctx.strokeStyle=`rgba(219,193,154,${alpha*.22})`;ctx.beginPath();ctx.arc(p.x,p.y,4+Math.sin(phase*3+i)*2,0,Math.PI*2);ctx.stroke();}});
if(core){const endPoints=[[.18,.43],[.23,.79],[.80,.36],[.81,.70]];endPoints.forEach(([x,y],i)=>{const ex=width*x,ey=height*y;ctx.beginPath();ctx.moveTo(cx,cy);ctx.quadraticCurveTo((cx+ex)/2,ey,ex,ey);ctx.setLineDash([2,5]);ctx.strokeStyle=i===['GS','BP','INS','ACC'].indexOf(state.domain)?'#dbc19a55':'#9ad7d42a';ctx.stroke();ctx.setLineDash([]);const p=(phase*.35+i*.26)%1;const px=(1-p)*(1-p)*cx+2*(1-p)*p*(cx+ex)/2+p*p*ex,py=(1-p)*(1-p)*cy+2*(1-p)*p*ey+p*p*ey;ctx.fillStyle=i%2?ice:gold;ctx.shadowColor=gold;ctx.shadowBlur=9;ctx.beginPath();ctx.arc(px,py,2,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;});const mask=ctx.createRadialGradient(cx,cy,0,cx,cy,radius*.65);mask.addColorStop(0,'#111719eb');mask.addColorStop(.6,'#111719b5');mask.addColorStop(1,'#11171900');ctx.fillStyle=mask;ctx.fillRect(cx-radius,cy-radius,radius*2,radius*2);}
}
function loop(t){if(stopped)return;if(!document.hidden&&t-last>32){if(state.motion)phase+=.0038;draw(t);last=t}raf=requestAnimationFrame(loop)}const onMove=e=>{const r=canvas.getBoundingClientRect();hover={x:(e.clientX-r.left)/r.width-.5,y:(e.clientY-r.top)/r.height-.5}};canvas.addEventListener('pointermove',onMove);const ro=new ResizeObserver(resize);ro.observe(canvas);resize();raf=requestAnimationFrame(loop);const cleanup=()=>{stopped=true;cancelAnimationFrame(raf);ro.disconnect();canvas.removeEventListener('pointermove',onMove)};animationHandles.push(cleanup);activeNetwork={draw};}
const VIEWS=['overview','matrix','tree','drivers','network','vc','actions'];
const META={overview:['Monday Cockpit','THAILAND DEALER OPERATIONS / 01','A stronger Monday','One view of last week. A clear move for this week.'],matrix:['21 Core KPIs','5 BUSINESS AREAS / 21 CORE KPIs','Every signal matters','The agreed KPI set. Actuals, references and opportunities in one place.'],tree:['KPI Explorer','CORE → DRIVER → PROCESS / 03','Follow the why','Explore the source KPI structure, one connected branch at a time.'],drivers:['Opportunity Lab','FROM INSIGHT TO IMPACT / 04','Make the next move count','Move the operating levers. Compare scenarios. Commit to an action.'],network:['Dealer Network','154 DEALERS / THAILAND / 05','Grow stronger, together','Compare similar dealers and learn from the practices behind the numbers.'],vc:['VC Roadmap','VALUE CHAIN ABSORPTION / 06','Toward ninety. And beyond','Connect GS, BP, insurance, accessories and fixed-cost improvement.'],actions:['Action Studio','MONDAY TO MOMENTUM / 07','Turn intent into progress','Give every opportunity an owner, a date and a next step.']};
const GROUPS={GS:'General Service',BP:'Body & Paint',INS:'Insurance',ACC:'Accessories',COST:'Fixed costs'};
const STORES={'BKK-001':{name:'Bangkok Central',region:'Bangkok',factor:1,ratio:72,peer:76},'CNX-001':{name:'Chiang Mai North',region:'North',factor:1.07,ratio:78,peer:77},'KKN-001':{name:'Khon Kaen East',region:'Northeast',factor:.91,ratio:68,peer:73},'HKT-001':{name:'Phuket South',region:'South',factor:1.03,ratio:75,peer:74}};
const SOURCE_LABELS={existing:'Existing business KPI',system:'System extract',dealer:'Dealer input'};
const STATUS_LABELS={ideal:'Above reference',on:'At / near reference',warn:'Priority gap',missing:'Awaiting input'};
const STORAGE_KEY='tmt-vc-command-en-v3';let saved={};try{saved=JSON.parse(localStorage.getItem(STORAGE_KEY))||{}}catch{}
let state={view:'overview',store:'BKK-001',period:'2026-10-05',category:'ALL',status:'all',compare:'hq',layout:'compact',horizon:13,driver:'tire',domain:'GS',treeMode:'core',region:'ALL',size:'ALL',sort:'ratio',page:0,compareDealers:['BKK-001','CNX-001'],motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,tires:8.4,bay:49,cost:0,year:2026,actions:[],tour:false,tourPaused:false,tourStep:0,tourElapsed:0};
let charts=[],animationHandles=[],drawerChart=null,previousFocus=null,toastTimer,tourTimer,activeNetwork=null,tourAutoTimers=[];
function storeInfo(){return STORES[state.store]}
function periodFactor(){return state.period==='2026-09-28'?.96:state.period==='2026-09-21'?.93:1}
function factor(){return storeInfo().factor*periodFactor()}
function ratioBase(){return storeInfo().ratio+(state.period==='2026-09-28'?-3:state.period==='2026-09-21'?-4.5:0)}
function storeSaved(){return saved[state.store]??={}}
function getActions(){const a=storeSaved().actions;return Array.isArray(a)&&a.every(x=>x.id&&['todo','doing','done'].includes(x.status))?structuredClone(a):structuredClone(INITIAL_ACTIONS)}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(saved))}catch{toast('Browser storage is unavailable. Changes remain in this session.')}}
function saveActions(){storeSaved().actions=state.actions;persist()}
state.actions=getActions();
function currentKpis(){return KPI_DATA.map(k=>{const entry=storeSaved().inputs?.[state.period]?.[k.id];const f=1+(factor()-1)*(k.direction===1?.7:-.35),value=entry?.value??+(k.value*f).toFixed(k.precision);const ready=entry?true:k.ready,progress=k.direction===1?value/k.target:k.target/(value||.001);let status=!ready?'missing':!entry&&state.store==='BKK-001'&&state.period==='2026-10-05'?k.baseStatus:progress>=1.02?'ideal':progress>=.95?'on':'warn';return {...k,value,ready,progress,status,edited:!!entry}})}
function benchmark(k){return state.compare==='peer'?k.peer:state.compare==='history'?k.history:k.target}
function compareName(){return {hq:'HTML reference',peer:'Peer average',history:'13-week average'}[state.compare]}
function conditionLabel(){return `${storeInfo().name} · Week of ${state.period}`}
function sampleNote(t='Source structures retained. Dealer results and operating scenarios are demonstration data.'){return `<p class="source-note">${t}</p>`}
function panelTitle(title,en,right=''){return `<div class="section-heading"><h2>${title}<small>${en}</small></h2>${right}</div>`}
function table(headers,rows,cls=''){return `<div class="table-scroll"><table class="tmt-table ${cls}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function disposeView(){charts.forEach(c=>c.destroy());charts=[];animationHandles.forEach(fn=>fn());animationHandles=[];activeNetwork=null}
function setView(name,options={}){if(!VIEWS.includes(name))name='overview';disposeView();state.view=name;const m=META[name];$('#breadcrumb').textContent=m[0];$('#pageEyebrow').textContent=m[1];$('#pageTitle').innerHTML=m[2]+'<span class="title-dot">.</span>';$('#pageSubtitle').textContent=m[3];$$('.nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.view===name);b.setAttribute('aria-current',b.dataset.view===name?'page':'false')});history.replaceState(null,'',`#${name}`);$('#viewRoot').innerHTML=`<section class="view" aria-label="${m[0]}">${({overview:renderOverview,matrix:renderMatrix,tree:renderTree,drivers:renderDrivers,network:renderNetwork,vc:renderVC,actions:renderActions})[name]()}</section>`;hydrate($('#viewRoot'));({overview:initOverview,matrix:initMatrix,tree:initTree,drivers:initDrivers,network:initNetwork,vc:initVC,actions:initActions})[name]();animateNumbers();enhanceView();if(options.scroll!==false)window.scrollTo({top:0,behavior:'instant'})}
function renderOverview(){const pending=state.actions.filter(a=>a.status!=='done').length;return `<div class="hero"><img class="hero-image" src="assets/vision.webp" alt="Silver concept vehicle in champagne-gold light" fetchpriority="high"><div class="hero-content"><p class="eyebrow">TOYOTA THAILAND / VALUE CHAIN</p><h2>Every opportunity.<br><em>In motion.</em></h2><p class="hero-description">Stronger service. Smarter capacity.<br>A clear path to greater dealer profitability.</p><div class="hero-actions"><button class="gold-button" data-driver="tire">Explore the opportunity ${icon('arrow')}</button><button class="text-button" data-action="tour">${icon('play')} Take the tour</button></div></div><div class="hero-label">154 DEALERS / ONE DIRECTION<span>VALUE CHAIN GROWTH</span></div><div class="hero-corner">MONDAY MORNING / THAILAND</div><div class="hero-caption"><i></i> CONCEPT VEHICLE</div></div><div class="manager-note"><span>${icon('spark')} THIS WEEK'S FOCUS</span><p>Service traffic is in place. Close the tire quotation gap and put available workbays to work.</p><button class="text-button" data-view="actions">Open the briefing →</button></div><div class="metric-grid">${metric('VC absorption',ratioBase(),'%','Reference 75%','Contribution / fixed costs','absorption','vc')}${metric('Service revenue',+(12.8*factor()).toFixed(1),'MB','↗ +4% vs last week','THB / million baht','sales','network')}${metric('Service gross margin',+(31+(factor()-1)*8).toFixed(1),'%','Reference 33%','Gross profit / sales','margin','vc')}${metric('Open actions',pending,'','For this week','To do + in progress','actions','actions')}</div><div class="domain-strip">${Object.entries(GROUPS).map(([g,n],i)=>`<button data-open-group="${g}"><span>${g}<small>${n}</small></span><b>${[68,81,74,92,55][i]}<small>%</small></b><i class="${[0,2,4].includes(i)?'warn':''}">${['Watch','On track','Watch','On track','Improve'][i]}</i></button>`).join('')}</div><div class="tmt-two"><article class="panel">${panelTitle('The direction of travel','VC ABSORPTION / SAMPLE TREND',`<div class="segmented"><button data-horizon="13" class="${state.horizon===13?'active':''}">13 weeks</button><button data-horizon="52" class="${state.horizon===52?'active':''}">1 year</button></div>`)}<div class="canvas-box"><canvas id="overviewChart" role="img" aria-label="VC absorption trend"></canvas></div><div class="chart-key"><span><i></i>Selected dealer</span><span><i class="ice"></i>Similar dealers</span><span>WEEKLY SAMPLE</span></div></article><article class="panel">${panelTitle('Signals worth acting on','PRIORITY ALERTS',tag('4 SIGNALS'))}<div class="signal-list">${[['gs-vc','HIGH','Tire penetration','8.4% · Challenge 19%'],['gs-bay','HIGH','Workbay utilization','49% · Reference 50%'],['ins-y35','WATCH','Insurance renewal Y3–5','46% · 13-week average 49%'],['cost-people','WATCH','Manpower cost','34% · Reference 32%']].map(([id,p,n,d])=>`<button class="signal-row text-button full-width" data-detail="${id}"><span class="priority-chip ${p==='HIGH'?'high':''}">${p}</span><div style="text-align:left"><strong>${n}</strong><small>${d}</small></div><span>↗</span></button>`).join('')}</div></article></div><div class="tmt-two"><article class="panel">${panelTitle('Where the tire opportunity sits','MONDAY HTML / QUOTATION FUNNEL',`<button class="text-button" data-driver="tire">Test the levers →</button>`)}<div class="compact-funnel">${[['Inspected',420],['Need replacement',82],['Quoted',54],['Sold',18]].map(([n,v],i)=>`<button data-funnel="${i}"><span>0${i+1} / ${n}</span><b>${v}</b><small>${['100% inspected','19.5% need replacement','65.9% quotation rate','33.3% quote conversion'][i]}</small></button>`).join('')}</div><p class="note">28 customers need a replacement but have no quotation. Start with the conversation, then secure the workbay.</p></article><article class="panel">${panelTitle('A like-for-like comparison','PEER BENCHMARK')}${table(['Measure','Your dealer','Peer average'],[['VC absorption',ratioBase().toFixed(1)+'%',storeInfo().peer+'%'],['GS revenue / head',(.69*factor()).toFixed(2)+' MB','0.72 MB'],['Tire penetration',(8.4*factor()).toFixed(1)+'%','12.1%'],['BP gross margin',(34*factor()).toFixed(1)+'%','32.0%']])}<p class="note">BP gross margin and the core KPI “BP contribution margin” are different measures.</p></article></div><article class="panel">${panelTitle('Four points for the morning briefing','THE WEEK STARTS HERE',`<button class="text-button" data-view="actions">Assign and track →</button>`)}<div class="brief-grid">${[['01','Inspection → quotation','Align every service advisor on the proposal.','TODAY'],['02','Make empty slots visible','Share available workbay capacity.','BY WEDNESDAY'],['03','Own the next renewal','Assign Y3–5 customers for follow-up.','BY FRIDAY'],['04','Match staffing to work','Review expected overtime and workload.','THIS WEEK']].map(v=>`<div><span>${v[0]}</span><h3>${v[1]}</h3><p>${v[2]}</p><small>${v[3]}</small></div>`).join('')}</div></article>${sampleNote('Based on the supplied Monday Store Manager Dashboard. Values are sample dealer results.')}`}
function initOverview(){const n=state.horizon,b=ratioBase(),labels=Array.from({length:n},(_,i)=>'W'+(i+1));const values=labels.map((_,i)=>b-7.2+i/(n-1)*7.2+Math.sin(i*.9)*.9);values[n-1]=b;lineChart('overviewChart',labels,[{label:'Selected dealer',data:values,borderColor:gold},{label:'Peer average',data:labels.map((_,i)=>storeInfo().peer-3.5+i/(n-1)*3.5),borderColor:ice,fill:false}]);['absorption','sales','margin','actions'].forEach((id,i)=>spark(id,[4,5,4.6,6,5.8,7,8,7.2,9,10],i%2?gold:ice));$$('[data-horizon]').forEach(b=>b.onclick=()=>{state.horizon=+b.dataset.horizon;setView('overview',{scroll:false})})}
function renderMatrix(){const list=currentKpis(),counts=Object.keys(STATUS_LABELS).map(s=>list.filter(k=>k.status===s).length);return `<div class="matrix-summary"><div><b>21</b><small>CORE KPIs</small></div>${counts.map((v,i)=>`<div><b style="color:${['var(--green)',gold,orange,'#88b6e4'][i]}">${String(v).padStart(2,'0')}</b><small>${Object.values(STATUS_LABELS)[i]}</small></div>`).join('')}<div class="summary-note">Explore the actuals.<br><span>Trace the process. Change the input.</span></div></div><div class="filter-toolbar"><div class="filter-tabs">${[['ALL','All'],...Object.entries(GROUPS)].map(([k,v])=>`<button data-category="${k}" class="${state.category===k?'active':''}">${k==='ALL'?v:k+' · '+v}</button>`).join('')}</div><div class="filter-right"><select id="compareFilter" class="filter-select" aria-label="Comparison"><option value="hq">HTML reference</option><option value="peer">Peer average</option><option value="history">13-week average</option></select><select id="statusFilter" class="filter-select" aria-label="KPI status"><option value="all">All statuses</option>${Object.entries(STATUS_LABELS).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><button class="ghost-button" id="matrixLayout">${state.layout==='compact'?'Expand evidence':'Compact view'}</button><button class="ghost-button" id="exportKpis">Export CSV ↗</button></div></div><div class="matrix-grid ${state.layout==='expanded'?'expanded':''}" id="matrixGrid">${renderKpiCards()}</div><div class="matrix-legend">${Object.entries(STATUS_LABELS).map(([s,l])=>`<span class="status-dot ${s}"><i></i>${l}</span>`).join('')}<span>Select any KPI to inspect, edit or explore its branch.</span></div><article class="panel readiness-panel">${panelTitle('Make the measures usable',`DATA READINESS / ${list.filter(k=>k.ready).length} OF 21`,`<button class="text-button" data-info="sources">Sources & definitions →</button>`)}<div class="readiness-grid">${Object.entries(GROUPS).map(([g,n])=>{const a=list.filter(k=>k.group===g),ready=a.filter(k=>k.ready).length;return `<div><span>${g} <small>${n}</small><b>${ready} / ${a.length}</b></span><div class="bar-track"><div class="bar-fill" style="width:${ready/a.length*100}%"></div></div></div>`}).join('')}</div><div class="data-source-legend">${Object.entries(SOURCE_LABELS).map(([k,l])=>`<span class="source-badge ${k}">${l}</span>`).join('')}</div><p class="note">PHYD awaits dealer input in the HTML sample. Open its card to enter a value and watch readiness change. Source-class assignments are illustrative.</p></article>`}
function renderKpiCards(){const a=currentKpis().filter(k=>(state.category==='ALL'||k.group===state.category)&&(state.status==='all'||k.status===state.status));return a.length?a.map(k=>{const b=benchmark(k),diff=k.value-b;return `<button class="kpi-card ${k.status}" data-detail="${k.id}"><div class="kpi-card-top"><span>${k.group} / ${String(k.i+1).padStart(2,'0')}</span><span class="status-dot ${k.status}"><i></i>${k.edited?'Edited':{ideal:'Above',on:'Near',warn:'Priority',missing:'Input'}[k.status]}</span></div><h3>${k.name}</h3><div class="kpi-number">${fmt(k.value)}<small>${k.unit}${!k.ready?' *':''}</small></div><div class="kpi-target"><span>${compareName()} ${b==null?'N/A':fmt(b)+k.unit}</span><b>${b==null?'—':signed(diff,k.precision||1)+(k.unit==='%'?'pt':'')}</b></div><div class="kpi-track"><span style="width:${Math.min(100,k.progress*85)}%"></span></div>${state.layout==='expanded'?`<div class="expanded-data"><p><span>ACTUALS</span>${k.actuals[0]}</p><p><span>OPPORTUNITY</span>${k.actuals[1]}</p><div>Peer ${k.peer} · 13W ${k.history??'N/A'} · Ref ${k.target}</div><small class="source-badge ${k.sourceType}">${SOURCE_LABELS[k.sourceType]}</small></div>`:''}</button>`}).join(''):'<div class="empty-state">No KPIs match this combination.<br>Choose another area or status.</div>'}
function initMatrix(){$('#compareFilter').value=state.compare;$('#statusFilter').value=state.status;$$('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;setView('matrix',{scroll:false})});$('#statusFilter').onchange=e=>{state.status=e.target.value;$('#matrixGrid').innerHTML=renderKpiCards()};$('#compareFilter').onchange=e=>{state.compare=e.target.value;$('#matrixGrid').innerHTML=renderKpiCards()};$('#matrixLayout').onclick=()=>{state.layout=state.layout==='compact'?'expanded':'compact';setView('matrix',{scroll:false})};$('#exportKpis').onclick=()=>downloadCSV('TMT_Core_KPIs.csv',[['Dealer','Week','Area','KPI','Actual','Unit','Reference','Peer','13-week average','Status'],...currentKpis().map(k=>[storeInfo().name,state.period,k.group,k.name,k.value,k.unit,k.target,k.peer,k.history??'',STATUS_LABELS[k.status]])])}
const DRIVERS={tire:{name:'Tire',en:'TIRE PENETRATION',value:8.4,target:8.5,counts:[420,82,54,18],unitProfit:800,copy:'28 customers need replacement but have no quotation.',source:'Monday HTML funnel / VC PDF p.2',action:'Review every replacement-required inspection, issue a quotation and offer an available workbay.'},battery:{name:'Battery',en:'BATTERY PENETRATION',value:5.2,target:5.2,counts:[350,56,38,18],unitProfit:550,copy:'Make the diagnosis visible. Make the next step simple.',source:'VC PDF p.2 average / illustrative funnel',action:'Explain the battery diagnosis and issue a replacement quotation where appropriate.'},air:{name:'Air care',en:'AIR CARE PENETRATION',value:6.9,target:7,counts:[420,94,60,29],unitProfit:240,copy:'Turn the condition check into a relevant service conversation.',source:'VC PDF p.2 average / illustrative funnel',action:'Show the condition of the filter and offer an appropriate air-care service.'}};
let labValues={},labChart=null;
function labDefaults(){if(DRIVERS[state.driver]){const d=DRIVERS[state.driver];return {proposal:Math.round(d.counts[2]/d.counts[1]*100),close:Math.round(d.counts[3]/d.counts[2]*100)}}return state.driver==='workbay'?{hours:5}:{tcare:35}}
function labResult(){const d=DRIVERS[state.driver];if(d){const quoted=Math.round(d.counts[1]*labValues.proposal/100),sales=Math.round(d.counts[1]*labValues.proposal/100*labValues.close/100);return {main:sales,unit:'sales',gain:sales-d.counts[3],money:(sales-d.counts[3])*d.unitProfit,quoted,baseline:d.counts[3]}}if(state.driver==='workbay'){const main=(245+labValues.hours)/500*100;return {main,unit:'% utilization',gain:main-49,money:labValues.hours*900,baseline:49}}const main=30+(labValues.tcare-35)*.25;return {main,unit:'% contribution',gain:main-30,money:(main-30)/100*12000000,baseline:30}}
function labSlider(id,label,min,max,value,step=1){return `<div class="slider-row"><label for="${id}Slider">${label}<small>${id==='hours'?'ADDITIONAL PRODUCTIVE HOURS':id==='tcare'?'T.CARE CPU MIX':'PROCESS CONVERSION'}</small></label><input type="range" id="${id}Slider" min="${min}" max="${max}" step="${step}" value="${value}"><output id="${id}Output"></output></div>`}
function renderDrivers(){labValues={...labDefaults(),...(storeSaved().lab?.[state.driver]||{})};const d=DRIVERS[state.driver];return `<div class="driver-tabs filter-tabs">${[['tire','Tire'],['battery','Battery'],['air','Air care'],['workbay','Workbay'],['bp','BP / T.CARE']].map(([k,n])=>`<button data-driver-tab="${k}" class="${state.driver===k?'active':''}">${n}</button>`).join('')}</div><div class="driver-hero"><div><p class="eyebrow">${d?'GS / '+d.en:state.driver==='workbay'?'GS / WORKBAY UTILIZATION':'BP / T.CARE CPU PENETRATION'}</p><h2>${d?d.copy:state.driver==='workbay'?'Put capacity back into motion.':'Improve the mix. Protect contribution.'}</h2><p>${d?'Move the quotation and conversion levers. See the opportunity update instantly.':state.driver==='workbay'?'Productive work / maximum capacity. Coordinate bookings, people and the next available slot.':'Connect insurance and BP. Review customer mix and the cost of discounts.'}</p></div><div class="driver-baseline"><small>${d?'PDF / CURRENT AVERAGE':'HTML / CURRENT SAMPLE'}</small><b>${d?d.value:state.driver==='workbay'?49:30}<span>%</span></b><p>${d?'Criterion ≥'+d.target+'%':state.driver==='workbay'?'245h used / 500h capacity':'Contribution / revenue'}</p></div></div><div class="tmt-two driver-main"><article class="panel">${panelTitle(d?'From inspection to conversion':state.driver==='workbay'?'Unused hours are an opportunity':'The BP operating guidelines','BEFORE → AFTER / LIVE SCENARIO',tag('INTERACTIVE'))}${d?`<div class="funnel-canvas"><canvas id="labChart" role="img" aria-label="Baseline and scenario funnel"></canvas></div><div class="chart-key"><span><i class="ice"></i>Baseline</span><span><i></i>Scenario</span></div><div class="lab-stage-buttons">${['Inspection','Replacement needed','Quotation','Sale'].map((l,i)=>`<button data-lab-stage="${i}">${l}<b>${d.counts[i]}</b></button>`).join('')}</div><p class="note">${d.source}. The PDF average and the single-dealer funnel have different populations.</p>`:state.driver==='workbay'?`<div class="wb-comparison"><div><strong>102</strong><span>dealers below 50%</span><small>66% OF 154 / PDF p.5</small></div><div><strong>52</strong><span>dealers at or above 50%</span><small>34% OF 154</small></div></div><div class="capacity-track"><div id="capacityFill"></div><span>500h capacity</span></div><div class="reference-levels"><div><small>NORM / p.2</small><b>≥47%</b></div><div><small>CRITERION</small><b>≥50%</b></div><div><small>IDEAL EXAMPLE / p.5</small><b>55%</b></div></div><p class="note">PDF p.5: DLR A 40%, DLR B 47%, DLR C 55%. The source selects 50% as the practical improvement guideline.</p>`:table(['Measure','Current','Norm','Criterion'],[['WB utilization','80%','>80%','100%'],['Tech / active WB','87%','>90%','100%'],['CPU / UIO','24%','>25%','>30%'],['Contribution margin','30%','>30%','>35%'],['T.CARE CPU mix','35%','>35%','>40%']])}</article><article class="panel lab-controls">${panelTitle('Change a lever. Watch the outcome.','SCENARIO BUILDER',`<button class="text-button" id="labReset">Reset ↺</button>`)}${d?`<div class="preset-row">${[['baseline','Baseline'],['coverage','Full quotation'],['conversion','High conversion']].map(([k,n])=>`<button data-lab-preset="${k}">${n}</button>`).join('')}</div>${labSlider('proposal','Quotation rate',50,100,labValues.proposal)}${labSlider('close','Quotation → sale',20,70,labValues.close)}`:state.driver==='workbay'?labSlider('hours','Additional work',0,100,labValues.hours,5):labSlider('tcare','T.CARE CPU mix',35,60,labValues.tcare)}<div class="driver-sim-result"><div><small>SCENARIO RESULT</small><b id="labMain"></b></div><div><small>CHANGE VS BASELINE</small><b class="ice-text" id="labGain"></b></div></div><div class="lab-money"><span>Illustrative ${state.driver==='workbay'?'revenue':'contribution'} change</span><b id="labMoney"></b></div><button class="gold-button full-width" id="driverAction">Build an action from this ${icon('arrow')}</button><p class="note">${d?`Required replacements × quotation rate × conversion. Illustrative contribution: THB ${d.unitProfit} per extra sale.`:state.driver==='workbay'?'(245h + added hours) / 500h. Revenue illustration: THB 900 per additional productive hour.':'Illustrative sensitivity: +0.25pt contribution margin per +1pt T.CARE mix, on THB 12M revenue. This is a scenario assumption.'}</p></article></div><article class="panel scenario-shelf">${panelTitle('Put two ideas side by side','SAVE A / SAVE B / RESTORE',`<div class="filter-right"><button class="ghost-button" data-save-scenario="A">Save as A</button><button class="ghost-button" data-save-scenario="B">Save as B</button></div>`)}<div class="scenario-comparison" id="scenarioCards"></div></article>${d?`<div class="tmt-two"><article class="panel">${panelTitle('Penetration and productivity','VC PDF p.2 / ORIGINAL GUIDELINES')}${table(['Measure','Current','Criterion','Challenge'],[['Tire','8.4%','≥8.5%','≥19%'],['Battery','5.2%','≥5.2%','Step improvement'],['Air care','6.9%','≥7%','Step improvement'],['Revenue / head / year','0.71 MB','≥0.70 MB','≥0.95 MB']])}</article><article class="panel">${panelTitle('Bill C planning','2026 → 2030 / INDEXED TO 2026')}${table(['Revenue scope','2026','2030'],[['GS Pure / excluding tire','100','109'],['GS Pure + tire','100','122']])}<button class="text-button" data-tree-jump="tire">Explore the source process tree →</button></article></div>`:state.driver==='bp'?`<article class="panel">${panelTitle('Understand the discount structure','VC PDF p.3 / T.CARE CPU CHALLENGE >50%')}${table(['Customer type','T.CARE','Non T.CARE','Cash'],[['Parts discount','−15%','−20% or more','−5%'],['Labor discount','−15%','−20% or more','−5%']])}</article>`:`<article class="panel">${panelTitle('Capacity starts with the appointment','CORE → DRIVER → PROCESS')}<div class="process-line"><div><small>CORE KPI</small><strong>Workbay utilization</strong></div><b>→</b><div><small>DRIVER</small><strong>PM Appointment</strong></div><b>→</b><div><small>PROCESS</small><strong>Contact → Success</strong></div></div><button class="gold-button" data-tree-jump="appointment">Explore the appointment branches ${icon('arrow')}</button></article>`}`}
function updateLab(){const d=DRIVERS[state.driver],r=labResult();Object.keys(labValues).forEach(k=>{const out=$('#'+k+'Output');if(out)out.textContent=labValues[k]+(k==='hours'?'h':'%')});$('#labMain').innerHTML=fmt(r.main,d?0:1)+`<small>${r.unit}</small>`;$('#labGain').innerHTML=signed(r.gain,d?0:1)+`<small>${d?'sales':'pt'}</small>`;$('#labMoney').textContent=(r.money<0?'−':'+')+'THB '+fmt(Math.abs(r.money),0);if(d&&labChart){labChart.data.datasets[1].data=[d.counts[0],d.counts[1],r.quoted,r.main];labChart.update('none')}if($('#capacityFill'))$('#capacityFill').style.width=r.main+'%';storeSaved().lab??={};storeSaved().lab[state.driver]={...labValues};persist()}
function renderScenarioCards(){const scenarios=storeSaved().scenarios?.[state.driver]||{};$('#scenarioCards').innerHTML=['A','B'].map(slot=>{const s=scenarios[slot];return `<div class="saved-scenario ${s?'filled':''}"><span>SCENARIO ${slot}</span>${s?`<b>${fmt(s.result.main)}<small>${s.result.unit}</small></b><p>${Object.entries(s.values).map(([k,v])=>`${k==='proposal'?'Quotation':k==='close'?'Conversion':k==='hours'?'Extra hours':'T.CARE'} ${v}${k==='hours'?'h':'%'}`).join(' · ')}</p><button class="text-button" data-load-scenario="${slot}">Restore scenario ${slot} ↗</button>`:'<p>Move the levers and save this idea.</p>'}</div>`}).join('');$$('[data-load-scenario]').forEach(b=>b.onclick=()=>{labValues={...scenarios[b.dataset.loadScenario].values};Object.entries(labValues).forEach(([k,v])=>$('#'+k+'Slider').value=v);updateLab();toast('Scenario '+b.dataset.loadScenario+' restored')})}
function initDrivers(){$$('[data-driver-tab]').forEach(b=>b.onclick=()=>{state.driver=b.dataset.driverTab;setView('drivers',{scroll:false})});const d=DRIVERS[state.driver];labChart=null;if(d){labChart=new Chart($('#labChart'),{type:'bar',data:{labels:['Inspected','Need replacement','Quoted','Sold'],datasets:[{label:'Baseline',data:d.counts,backgroundColor:'#9ad7d44d',borderRadius:3},{label:'Scenario',data:d.counts,backgroundColor:gold,borderRadius:3}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{color:'#ffffff08'},border:{display:false}},y:{grid:{display:false},border:{display:false},ticks:{color:'#bfc9cb',font:{size:10}}}}}});charts.push(labChart)}Object.keys(labValues).forEach(k=>$('#'+k+'Slider').oninput=e=>{labValues[k]=+e.target.value;updateLab()});updateLab();renderScenarioCards();$('#labReset').onclick=()=>{labValues=labDefaults();Object.entries(labValues).forEach(([k,v])=>$('#'+k+'Slider').value=v);updateLab()};$$('[data-lab-preset]').forEach(b=>b.onclick=()=>{labValues=b.dataset.labPreset==='baseline'?labDefaults():{proposal:100,close:b.dataset.labPreset==='coverage'?labDefaults().close:50};Object.entries(labValues).forEach(([k,v])=>$('#'+k+'Slider').value=v);updateLab()});$$('[data-save-scenario]').forEach(b=>b.onclick=()=>{storeSaved().scenarios??={};storeSaved().scenarios[state.driver]??={};storeSaved().scenarios[state.driver][b.dataset.saveScenario]={values:{...labValues},result:labResult()};persist();renderScenarioCards();toast('Scenario '+b.dataset.saveScenario+' saved for this dealer')});$$('[data-lab-stage]').forEach(b=>b.onclick=()=>{const i=+b.dataset.labStage;openDrawer(`<p class="eyebrow">${d.name.toUpperCase()} / PROCESS EVIDENCE</p><h2>${['Inspection','Replacement required','Quotation','Sale'][i]}</h2><div class="drawer-big">${d.counts[i]}<small>customers</small></div><p class="drawer-subtitle">${['Start with the inspection population.','Identify customers with a replacement need.','Explain the result and issue a relevant quotation.','Convert the quotation into a scheduled job.'][i]}</p><div class="drawer-callout">${i===2?`${d.counts[1]-d.counts[2]} replacement-required customers have no quotation.`:'Click the scenario controls to explore the next process improvement.'}</div><p class="note">${d.source}. Sample customer counts.</p>`) });$('#driverAction').onclick=()=>{const r=labResult();addAction({id:'lab-'+state.driver,group:state.driver==='bp'?'BP':'GS',title:d?'Improve '+d.name.toLowerCase()+' proposal conversion':state.driver==='workbay'?'Activate the next available workbay hours':'Review T.CARE customer mix',description:d?d.action:state.driver==='workbay'?'Share available capacity with reception and agree the bookings needed to fill it.':'Coordinate BP and insurance teams to review customer mix and discount practices.',impact:`Scenario: ${fmt(r.main)} ${r.unit} (${signed(r.gain)} ${d?'sales':'pt'} vs baseline)`})}}
const REGIONS=['Bangkok','Central','North','Northeast','South'];
function seeded(i,salt){let x=Math.imul(i+17,salt+7919)^0x51ab3;return ((Math.imul(x^(x>>>16),73244475)>>>0)%10000)/10000}
const DEALERS=Array.from({length:154},(_,i)=>({id:'TH-'+String(i+1).padStart(3,'0'),name:['Bangkok','Ayutthaya','Chiang Mai','Khon Kaen','Phuket'][i%5]+' '+String(Math.floor(i/5)+1).padStart(2,'0'),region:REGIONS[i%5],size:['Large','Medium','Small'][i%3],ratio:+(59+seeded(i,37)*33).toFixed(1),wb:+(i<103?35+seeded(i,29)*14.7:50+seeded(i,29)*25).toFixed(1),tire:+(5+seeded(i,41)*15).toFixed(1),margin:+(25+seeded(i,19)*14).toFixed(1),ready:17+i%5}));
Object.entries(STORES).forEach(([id,s],i)=>Object.assign(DEALERS[i],{id,name:s.name,region:s.region,ratio:s.ratio,wb:[49,54,44,48][i],tire:+(8.4*s.factor).toFixed(1)}));
function networkRows(){return DEALERS.filter(d=>(state.region==='ALL'||d.region===state.region)&&(state.size==='ALL'||d.size===state.size)).sort((a,b)=>state.sort==='name'?a.name.localeCompare(b.name):b[state.sort]-a[state.sort])}
function renderNetwork(){const a=networkRows();return `<div class="network-top"><article class="panel network-hero-panel">${panelTitle('Every dealer is part of the picture','THAILAND / VALUE CHAIN NETWORK',tag('154 / DEMO'))}<div class="network-preview large-network"><canvas id="networkPreview" class="network-canvas" role="img" aria-label="Animated dealer network"></canvas><div class="network-over-label">GS · BP · INSURANCE · ACCESSORIES · COST</div><div class="network-overlay"><div>154<small>DEALERS</small></div><div>05<small>BUSINESS AREAS</small></div><div>21<small>CORE KPIs</small></div></div></article><article class="panel">${panelTitle('Compare context, then performance','LIKE-FOR-LIKE BENCHMARK')}<div class="reference-levels"><div><small>SELECTED DEALERS</small><b>${a.length}</b></div><div><small>MEAN VC ABSORPTION</small><b>${(a.reduce((s,d)=>s+d.ratio,0)/(a.length||1)).toFixed(1)}%</b></div><div><small>PDF BASELINE</small><b>70%</b></div></div><p class="note">Filter by region and scale. Compare two dealers, then investigate their appointment routines, proposal habits and staff allocation.</p><div class="network-insight">${icon('spark')}<span>Look beyond rank. Find the practice that another team can repeat.</span></div></article></div><div class="filter-toolbar"><div class="filter-tabs">${['ALL',...REGIONS].map(r=>`<button data-region="${r}" class="${state.region===r?'active':''}">${r==='ALL'?'All Thailand':r}</button>`).join('')}</div><select class="filter-select" id="sizeFilter" aria-label="Dealer size">${['ALL','Large','Medium','Small'].map(v=>`<option value="${v}" ${state.size===v?'selected':''}>${v==='ALL'?'All sizes':v}</option>`).join('')}</select></div><div class="tmt-two"><article class="panel">${panelTitle('Capacity meets contribution','WORKBAY × VC ABSORPTION',tag('CLICK A DEALER'))}<div class="canvas-box network-chart"><canvas id="dealerScatter" role="img" aria-label="Dealer workbay and absorption scatter plot"></canvas></div><div class="chart-key"><span><i class="ice"></i>≥80%</span><span><i></i>70–80%</span><span><i style="background:#dd9b75"></i>&lt;70%</span></div></article><article class="panel compare-panel">${panelTitle('Two dealers. One useful conversation.','SIDE-BY-SIDE COMPARISON')}<div class="dealer-compare-selects">${[0,1].map((n)=>`<label>DEALER ${n?'B':'A'}<select class="filter-select" id="compareDealer${n}">${DEALERS.map(d=>`<option value="${d.id}" ${state.compareDealers[n]===d.id?'selected':''}>${d.name}</option>`).join('')}</select></label>`).join('')}</div><div id="dealerComparison"></div></article></div><article class="panel">${panelTitle('Dealer benchmark','154 SYNTHETIC RECORDS',`<select class="filter-select" id="sortDealer" aria-label="Sort dealers">${[['ratio','VC absorption'],['wb','Workbay utilization'],['tire','Tire penetration'],['name','Dealer name']].map(([v,n])=>`<option value="${v}" ${state.sort===v?'selected':''}>${n}</option>`).join('')}</select>`)}<div id="dealerTable">${renderDealerTable()}</div></article>${sampleNote('Dealer names and results are synthetic. The PDF network reference remains 154 dealers, with 102 below 50% workbay utilization.')}`}
function renderDealerTable(){const rows=networkRows(),pages=Math.ceil(rows.length/8);state.page=Math.max(0,Math.min(state.page,pages-1));return table(['Dealer','Region / size','VC absorption','WB utilization','Tire penetration',''],rows.slice(state.page*8,state.page*8+8).map(d=>[`${d.name}<small>${d.id}</small>`,`${d.region}<small>${d.size}</small>`,d.ratio+'%',d.wb+'%',d.tire+'%',`<button class="text-button" data-dealer="${d.id}">Inspect ↗</button>`]))+`<div class="table-pagination"><span>${state.page*8+1}–${Math.min(rows.length,state.page*8+8)} / ${rows.length} dealers</span><div><button class="ghost-button" data-page="-1" ${state.page===0?'disabled':''}>← Previous</button><button class="ghost-button" data-page="1" ${state.page>=pages-1?'disabled':''}>Next →</button></div></div>`}
function renderDealerComparison(){const [a,b]=state.compareDealers.map(id=>DEALERS.find(d=>d.id===id));$('#dealerComparison').innerHTML=table(['Measure','A','B','B − A'],[['VC absorption',a.ratio+'%',b.ratio+'%',signed(b.ratio-a.ratio)+'pt'],['WB utilization',a.wb+'%',b.wb+'%',signed(b.wb-a.wb)+'pt'],['Tire penetration',a.tire+'%',b.tire+'%',signed(b.tire-a.tire)+'pt'],['BP margin',a.margin+'%',b.margin+'%',signed(b.margin-a.margin)+'pt']])+`<p class="note">${a.name} (${a.size}, ${a.region}) vs ${b.name} (${b.size}, ${b.region}). ${a.size!==b.size||a.region!==b.region?'Context differs; use this comparison to frame a question.':'The dealers share a size and region segment.'}</p>`}
function initNetwork(){makeNetwork($('#networkPreview'),'preview');const rows=networkRows();const c=new Chart($('#dealerScatter'),{type:'scatter',data:{datasets:[{data:rows.map(d=>({x:d.wb,y:d.ratio,id:d.id,name:d.name})),pointRadius:4,pointHoverRadius:7,pointBackgroundColor:rows.map(d=>d.ratio>=80?ice:d.ratio>=70?gold:orange),borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,plugins:{tooltip:{callbacks:{label:c=>`${c.raw.name}: WB ${c.raw.x}%, VC ${c.raw.y}%`}}},onClick:(e,els)=>{if(els.length)openDealer(rows[els[0].index].id)},scales:{x:{min:30,max:80,title:{display:true,text:'Workbay utilization (%)'},grid:{color:'#ffffff07'},border:{display:false}},y:{min:50,max:100,title:{display:true,text:'VC absorption (%)'},grid:{color:'#ffffff07'},border:{display:false}}}}});charts.push(c);$$('[data-region]').forEach(b=>b.onclick=()=>{state.region=b.dataset.region;state.page=0;setView('network',{scroll:false})});$('#sizeFilter').onchange=e=>{state.size=e.target.value;state.page=0;setView('network',{scroll:false})};$('#sortDealer').onchange=e=>{state.sort=e.target.value;state.page=0;$('#dealerTable').innerHTML=renderDealerTable()};[0,1].forEach(i=>$('#compareDealer'+i).onchange=e=>{state.compareDealers[i]=e.target.value;renderDealerComparison()});renderDealerComparison()}
function openDealer(id){const d=DEALERS.find(x=>x.id===id);openDrawer(`<p class="eyebrow">DEALER INTELLIGENCE / ${d.id}</p><h2>${d.name}</h2><p class="drawer-subtitle">${d.region} · ${d.size} dealer · Synthetic record</p><div class="drawer-big">${d.ratio}<small>% VC absorption</small></div>${table(['Operating measure','Value'],[['Workbay utilization',d.wb+'%'],['Tire penetration',d.tire+'%'],['BP contribution margin',d.margin+'%'],['KPI readiness',d.ready+' / 21']])}<div class="drawer-callout">${d.wb<50?'Start with appointment coverage and available workbay slots.':'Investigate how the team coordinates bookings and technician allocation.'} ${d.tire<12?'Review inspection-to-quotation conversion.':'Share the proposal habits behind tire penetration.'}</div><button class="gold-button full-width" id="compareThisDealer">Compare as Dealer B ${icon('arrow')}</button>${STORES[id]?'<button class="ghost-button full-width" id="openThisDealer">Switch the entire workspace to this dealer</button>':''}`);$('#compareThisDealer').onclick=()=>{state.compareDealers[1]=id;closeDrawer();setView('network',{scroll:false});$('#dealerComparison').scrollIntoView({block:'center',behavior:state.motion?'smooth':'instant'})};if($('#openThisDealer'))$('#openThisDealer').onclick=()=>{closeDrawer();changeStore(id)}}
function projectedRatio(year=state.year){const growth=(year-2026)*4.5,operating=(state.tires-8.4)*.34+(state.bay-49)*.12;return Math.min(120,(ratioBase()+growth+operating)/(1-state.cost/100))}
function renderVC(){return `<div class="roadmap-milestones">${[['BASELINE','70','May 2026'],['2026 YEAR-END','72','Phase 1 / 21 KPIs'],['2027 PLAN','81','GS · BP · insurance + improvement'],['2030 PLAN','≈90','Including cost improvement & ACC']].map((v,i)=>`<div><span>${v[0]}</span><b>${v[1]}<small>%</small></b><p>${v[2]}</p>${i<3?'<i>→</i>':''}</div>`).join('')}</div><div class="vc-top"><article class="panel absorption-panel">${panelTitle('Cover more of the fixed-cost base','VC CONTRIBUTION / FIXED COSTS',tag('LIVE SCENARIO'))}<div class="gauge-wrap"><canvas id="gaugeChart" role="img" aria-label="VC absorption scenario gauge"></canvas><div class="gauge-center"><b id="ratioValue"></b><span>%</span><small id="ratioLabel">SELECTED DEALER</small></div></div><div class="gauge-comparison"><span>Baseline<b>${ratioBase().toFixed(1)}%</b></span><span>Long-term direction<b>90%</b></span><span>Full cost coverage<b>100%</b></span></div><div class="ratio-formula">Aftersales contribution ÷ fixed costs × 100</div></article><article class="panel scenario-panel"><div class="scenario-topline"><p class="eyebrow">WHAT IF / DEALER GROWTH</p><button class="text-button" id="resetScenario">RESET ↺</button></div><h2 class="scenario-title">The next move is <em>in your hands.</em></h2><p class="note">Explore the sensitivity to penetration, productive capacity and fixed costs.</p>${[['tire','Tire penetration',8.4,19,.1,state.tires],['bay','Workbay utilization',49,80,1,state.bay],['cost','Fixed-cost reduction',0,15,.5,state.cost]].map(([id,l,min,max,step,v])=>`<div class="slider-row"><label for="${id}Slider">${l}</label><input id="${id}Slider" type="range" min="${min}" max="${max}" step="${step}" value="${v}"><output id="${id}Output"></output></div>`).join('')}<div class="scenario-result"><div><small>CHANGE VS CURRENT DEALER</small><b id="scenarioGain"></b></div><button class="ghost-button" id="applyScenario">Build an action ${icon('arrow')}</button></div></article></div><div class="tmt-two"><article class="panel">${panelTitle('A path you can explore','ILLUSTRATIVE DEALER TRAJECTORY')}<div class="canvas-box"><canvas id="projectionChart" role="img" aria-label="Illustrative absorption trajectory"></canvas></div><div class="slider-row"><label for="yearSlider">Horizon</label><input id="yearSlider" type="range" min="2026" max="2030" value="${state.year}"><output id="yearOutput"></output></div><p class="note">Demo model: (dealer baseline + 4.5pt per year + 0.34pt per extra tire point + 0.12pt per extra WB point) / (1 − cost reduction). Separate from the source plan.</p></article><article class="panel">${panelTitle('The source plan, in its own terms','VC PDF p.1 / CONTRIBUTION LOGIC')}${table(['Stage','Contribution / improvement','Absorption'],[['Current','GS 44 + BP 20 + INS 6','70%'],['All dealers at criterion','GS 50 + BP 25 + INS 10','85%'],['2027 plan','GS 46 + BP 24 + INS 6<br>+ cost reduction 3 + ACC 2','81%'],['2030 plan','Core 82 + cost reduction 6 + ACC 2','90%']])}<p class="note">Contributions are percentage points. The 85% criterion case excludes cost reduction and is a different reference case from the year-based plan.</p></article></div><div class="tmt-two"><article class="panel phase-panel">${panelTitle('Phase 1: establish the operating rhythm','START IMPLEMENTATION / OCTOBER 2026')}<div class="phase-domains">${Object.keys(GROUPS).map(g=>`<button data-open-group="${g}">${g}<small>${GROUPS[g]}</small></button>`).join('')}</div><ol><li>Monitor the agreed 21 core KPIs.</li><li>RA / RO investigate dealer gaps and agree improvement plans.</li><li>Track activity and evaluate the result.</li><li>Share repeatable practices across the network.</li></ol></article><article class="panel phase-panel">${panelTitle('Phase 2: build the additional businesses','UNDER DEVELOPMENT / SOURCE PLAN')}<div class="future-businesses"><div><strong>USED CAR</strong><span>Additional business</span></div><div><strong>FIXFIT</strong><span>Additional business</span></div></div><p class="note">PDF p.6 targets development of additional businesses within 2026. Core KPI adoption comes first.</p><div class="potential-number"><small>FUTURE POTENTIAL / PDF p.1</small><b>92.2% <span>+ α</span></b></div></article></div>${sampleNote('VC PDF p.1 and p.6. The 2030 headline says 89% while the chart says 90%; the overview uses approximately 90%.')}`}
function updateScenario(){const ratio=projectedRatio();$('#ratioValue').textContent=ratio.toFixed(1);$('#ratioLabel').textContent=state.year+' / DEMO SCENARIO';$('#scenarioGain').innerHTML=signed(ratio-ratioBase())+'<small>pt</small>';$('#yearOutput').textContent=state.year;['tire','bay','cost'].forEach(k=>$('#'+k+'Output').textContent=(k==='tire'?state.tires:state[k])+'%');const g=charts[0];g.data.datasets[0].data=[Math.min(100,ratio),Math.max(0,100-ratio)];g.update('none');const p=charts[1];p.data.datasets[0].data=[2026,2027,2028,2029,2030].map(y=>projectedRatio(y));p.update('none')}
function initVC(){const g=new Chart($('#gaugeChart'),{type:'doughnut',data:{datasets:[{data:[ratioBase(),100-ratioBase()],backgroundColor:[gold,'#ffffff08'],borderWidth:0,borderRadius:3,spacing:2,weight:1},{data:[90,10],backgroundColor:['#9ad7d450','#ffffff03'],borderWidth:0,weight:.13}]},options:{responsive:true,maintainAspectRatio:false,cutout:'86%',rotation:220,circumference:280,events:[],plugins:{tooltip:{enabled:false}},animation:state.motion?{duration:900}:false,layout:{padding:8}}});charts.push(g);lineChart('projectionChart',['2026','2027','2028','2029','2030'],[{label:'Scenario',data:[2026,2027,2028,2029,2030].map(y=>projectedRatio(y)),borderColor:gold},{label:'Baseline extension',data:[0,1,2,3,4].map(i=>ratioBase()+i*1.7),borderColor:ice,borderDash:[4,4],fill:false}],{scales:{x:{border:{display:false},grid:{display:false}},y:{min:50,max:120,border:{display:false},grid:{color:'#ffffff08'},ticks:{callback:v=>v+'%'}}}});['tire','bay','cost'].forEach(k=>$('#'+k+'Slider').oninput=e=>{state[k==='tire'?'tires':k]=+e.target.value;updateScenario()});$('#yearSlider').oninput=e=>{state.year=+e.target.value;updateScenario()};$('#resetScenario').onclick=()=>{Object.assign(state,{tires:8.4,bay:49,cost:0,year:2026});setView('vc',{scroll:false})};$('#applyScenario').onclick=()=>addAction({id:'vc-plan',group:'VC',title:'Agree the dealer growth scenario',description:`Review tire penetration ${state.tires}%, workbay utilization ${state.bay}% and fixed-cost reduction ${state.cost}%. Agree owners and a realistic sequence.`,impact:`${state.year} illustrative VC absorption: ${projectedRatio().toFixed(1)}%`});updateScenario()}
function addAction(a){const exists=state.actions.find(x=>x.id===a.id);if(exists){closeDrawer();setView('actions');toast('This action is already in the plan. Edit it to refine the details.');return}state.actions.push({...a,owner:'DM',ownerName:'Dealer manager',due:'2026-10-09',status:'todo',priority:'OPPORTUNITY'});saveActions();closeDrawer();toast('Added to Action Studio');}
function renderActionCard(a){return `<article class="action-card ${a.status==='done'?'done-card':''}" draggable="true" data-action-id="${escapeHtml(a.id)}"><div class="action-priority"><span>${a.status==='done'?'COMPLETED':a.status==='doing'?'IN PROGRESS':escapeHtml(a.priority)}</span><span>${escapeHtml(a.group)}</span></div><h3>${escapeHtml(a.title)}</h3><p>${escapeHtml(a.description)}</p><div class="action-impact">↗ ${escapeHtml(a.impact)}</div><div class="action-meta"><span class="avatar">${escapeHtml(a.owner)}</span><span>${escapeHtml(a.ownerName)}</span><span>${escapeHtml(a.due)}</span></div><div class="action-buttons"><button class="action-move" data-move="${escapeHtml(a.id)}">${a.status==='todo'?'Start action':a.status==='doing'?'Mark complete':'Reopen'} ${icon(a.status==='doing'?'check':'arrow')}</button><button class="ghost-button" data-edit-action="${escapeHtml(a.id)}" aria-label="Edit ${escapeHtml(a.title)}">Edit</button></div></article>`}
function renderActions(){const done=state.actions.filter(a=>a.status==='done').length;return `<div class="action-hero"><div><p class="eyebrow">MONDAY BRIEFING / ${storeInfo().name.toUpperCase()}</p><h2>Five minutes on Monday.<br><em>Momentum for the week.</em></h2><p>Close the quotation gap. Fill the next workbay.<br>Make every commitment visible.</p></div><div class="action-completion"><b>${String(done).padStart(2,'0')}<small> / ${String(state.actions.length).padStart(2,'0')}</small></b><span>ACTIONS COMPLETED</span><div class="bar-track"><div class="bar-fill" style="width:${state.actions.length?done/state.actions.length*100:0}%"></div></div></div></div><div class="action-toolbar"><p>Drag a card between columns, or use its status button. Select Edit to assign an owner and due date.</p><div><button class="ghost-button" id="exportActions">Export plan ↗</button><button class="gold-button" id="newAction">+ New action</button></div></div><div class="kanban">${[['todo','Next to move'],['doing','In progress'],['done','Completed']].map(([s,l])=>`<section class="kanban-column" data-drop-status="${s}" aria-label="${l}"><div class="column-heading"><span><i class="tiny-dot"></i>${l}</span><b>${state.actions.filter(a=>a.status===s).length}</b></div><div class="kanban-cards">${state.actions.filter(a=>a.status===s).map(renderActionCard).join('')||'<div class="empty-column">'+icon('check')+'<span>Bring the next commitment here.</span></div>'}</div></section>`).join('')}</div><div class="actions-foot"><p>Saved in this browser, separately for each dealer. No messages are sent.</p><button class="text-button" id="resetActions">Reset this dealer’s sample plan ↺</button></div>`}
function initActions(){$('#newAction').onclick=()=>editAction();$('#resetActions').onclick=()=>{state.actions=structuredClone(INITIAL_ACTIONS);saveActions();setView('actions',{scroll:false});toast('Sample action plan restored')};$('#exportActions').onclick=()=>downloadCSV('TMT_Action_Plan.csv',[['Dealer','Action','Area','Owner','Due date','Status','Description','Expected effect'],...state.actions.map(a=>[storeInfo().name,a.title,a.group,a.ownerName,a.due,a.status,a.description,a.impact])]);$$('[draggable="true"]').forEach(c=>{c.ondragstart=e=>{e.dataTransfer.setData('text/plain',c.dataset.actionId);e.dataTransfer.effectAllowed='move';c.classList.add('dragging-card')};c.ondragend=()=>c.classList.remove('dragging-card')});$$('[data-drop-status]').forEach(col=>{col.ondragover=e=>{e.preventDefault();col.classList.add('drop-target')};col.ondragleave=()=>col.classList.remove('drop-target');col.ondrop=e=>{e.preventDefault();const a=state.actions.find(a=>a.id===e.dataTransfer.getData('text/plain'));if(a){a.status=col.dataset.dropStatus;saveActions();setView('actions',{scroll:false})}col.classList.remove('drop-target')}})}
function editAction(id){const a=state.actions.find(a=>a.id===id)||{title:'',description:'',impact:'',ownerName:'Dealer manager',due:'2026-10-09',group:'GS',status:'todo'};openDrawer(`<p class="eyebrow">ACTION STUDIO / ${id?'EDIT COMMITMENT':'NEW COMMITMENT'}</p><h2>Make the next step clear.</h2><form id="actionForm" class="editor-form"><label>Action title<input name="title" maxlength="120" required value="${escapeHtml(a.title)}" placeholder="What will the team do?"></label><div class="form-pair"><label>Business area<select name="group">${['GS','BP','INS','ACC','COST','VC'].map(g=>`<option ${a.group===g?'selected':''}>${g}</option>`).join('')}</select></label><label>Status<select name="status">${[['todo','To do'],['doing','In progress'],['done','Completed']].map(([s,l])=>`<option value="${s}" ${a.status===s?'selected':''}>${l}</option>`).join('')}</select></label></div><label>Owner<input name="owner" maxlength="70" required value="${escapeHtml(a.ownerName)}"></label><label>Due date<input name="due" type="date" required value="${escapeHtml(a.due)}"></label><label>Next step<textarea name="description" rows="4" maxlength="500" required>${escapeHtml(a.description)}</textarea></label><label>Expected effect<input name="impact" maxlength="180" value="${escapeHtml(a.impact)}" placeholder="How will you know it helped?"></label><button class="gold-button full-width" type="submit">Save commitment ${icon('check')}</button></form>`);$('#actionForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const item={...a,id:id||'custom-'+Date.now(),title:f.get('title').trim(),group:f.get('group'),status:f.get('status'),ownerName:f.get('owner').trim(),owner:f.get('owner').trim().split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase(),due:f.get('due'),description:f.get('description').trim(),impact:f.get('impact').trim()||'Review at the next briefing',priority:a.priority||'OPPORTUNITY'};if(!item.title||!item.ownerName||!item.description)return;const i=state.actions.findIndex(x=>x.id===id);if(i>=0)state.actions[i]=item;else state.actions.push(item);saveActions();closeDrawer();setView('actions',{scroll:false});toast('Commitment saved')}}
function openKpi(id){const k=currentKpis().find(x=>x.id===id);if(!k)return;const b=benchmark(k);openDrawer(`<p class="eyebrow">21 CORE KPIs / ${k.group}</p><h2>${k.name}</h2><p class="drawer-subtitle">${conditionLabel()}<br>${k.headline}</p><div class="drawer-big">${fmt(k.value)}<small>${k.unit}${!k.ready?' / provisional':''}</small></div><div class="drawer-comparison"><span>${compareName()} <b>${b==null?'N/A':fmt(b)+k.unit}</b></span><span>Gap <b>${b==null?'—':signed(k.value-b,k.precision||1)+(k.unit==='%'?'pt':'')}</b></span></div><div class="formula-callout">${k.formula}</div><div class="detail-evidence"><div><span>SOURCE BASELINE / ACTUALS</span><strong>${k.actuals[0]}</strong></div><div><span>SOURCE BASELINE / OPPORTUNITY</span><strong>${k.actuals[1]}</strong></div></div><div class="detail-benchmarks"><span>Peer<b>${k.peer}${k.unit}</b></span><span>13 weeks<b>${k.history??'N/A'}${k.history==null?'':k.unit}</b></span><span>HTML reference<b>${k.target}${k.unit}</b></span></div><div class="drawer-section"><h3>13-WEEK PERFORMANCE</h3><div class="canvas-box" style="height:155px"><canvas id="detailChart" role="img" aria-label="13-week KPI trend"></canvas></div><p class="note">Illustrative trend and year-on-year change ${signed(k.yoy)}${k.unit==='%'?'pt':k.unit}. Source actuals above remain the original baseline example.</p></div>${k.pdf?`<div class="drawer-callout reference-callout">${k.pdf}</div>`:''}<div class="drawer-section"><h3>LEVELS & DATA READINESS</h3><div class="detail-levels"><span>Minimum<b>${fmt(k.min)}${k.unit}</b></span><span>Criterion<b>${fmt(k.target)}${k.unit}</b></span><span>Ideal<b>${fmt(k.ideal)}${k.unit}</b></span></div><p class="note">Supplementary level thresholds are demo settings. PDF reference values, where provided, are stated separately above.</p><span class="source-badge ${k.sourceType}">${SOURCE_LABELS[k.sourceType]}</span></div><form class="inline-input-form" id="kpiInputForm"><label for="kpiValueInput">${k.ready?'Try a different sample value':'Complete the dealer input'}<small>Updates this dealer and week in the KPI map.</small></label><div><input id="kpiValueInput" type="number" min="0" ${k.unit==='%'?'max="100"':''} step="0.01" value="${k.value}" required aria-label="Sample KPI value"><button class="gold-button" type="submit">Apply input</button></div><button type="button" class="text-button" id="resetKpiInput">Restore source sample ↺</button></form><div class="drawer-section"><h3>NEXT BEST ACTION</h3><div class="drawer-callout">${k.action}</div></div><div class="drawer-actions"><button class="gold-button" id="addKpiAction">Add to action plan ${icon('bolt')}</button><button class="ghost-button" id="detailTree">Explore KPI tree ${icon('arrow')}</button></div>`);const values=Array.from({length:13},(_,i)=>+(k.value*(.9+i*.008+Math.sin(i*1.2)*.018)).toFixed(Math.max(k.precision,1)));values[12]=k.value;drawerChart=new Chart($('#detailChart'),{type:'line',data:{labels:Array.from({length:13},(_,i)=>'W'+(i+1)),datasets:[{label:k.name,data:values,borderColor:gold,borderWidth:1.8,pointRadius:0,pointHoverRadius:4,tension:.35,fill:true,backgroundColor:'#dbc19a10'},{label:'HTML reference',data:Array(13).fill(k.target),borderColor:ice,borderDash:[3,4],pointRadius:0,borderWidth:1}]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},scales:{x:{grid:{display:false},ticks:{maxTicksLimit:4},border:{display:false}},y:{grid:{color:'#ffffff08'},border:{display:false}}}}});$('#addKpiAction').onclick=()=>addAction({id:'kpi-'+k.id,group:k.group,title:k.headline,description:k.action,impact:`${k.name}: ${fmt(k.value)}${k.unit} / reference ${fmt(k.target)}${k.unit}`});$('#detailTree').onclick=()=>{closeDrawer();revealTree(k.group==='GS'?({'gs-crt':'crt','gs-job':'pm','gs-vc':'tire','gs-head':'revenue-unit','gs-bay':'appointment'}[id]||'core-'+id):'core-'+id);setView('tree');renderTreeCanvas(true)};$('#kpiInputForm').onsubmit=e=>{e.preventDefault();const value=+$('#kpiValueInput').value;if(!Number.isFinite(value)||value<0||(k.unit==='%'&&value>100))return;storeSaved().inputs??={};storeSaved().inputs[state.period]??={};storeSaved().inputs[state.period][id]={value:+value.toFixed(k.precision)};persist();closeDrawer();setView(state.view,{scroll:false});toast(k.name+' updated for this dealer and week')};$('#resetKpiInput').onclick=()=>{if(storeSaved().inputs?.[state.period])delete storeSaved().inputs[state.period][id];persist();closeDrawer();setView(state.view,{scroll:false});toast('Source sample restored')}}
function downloadCSV(name,rows){const content='\uFEFF'+rows.map(row=>row.map(v=>{let s=String(v??'');if(typeof v!=='number'&&/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV export ready')}
function openSourceNotes(){openDrawer(`<p class="eyebrow">SOURCE & MEASUREMENT NOTES</p><h2>The source structure, carried through.</h2><div class="guide-list"><div><b>01</b><span><strong>21 Core KPI Matrix / supplied HTML</strong>Five business areas: GS 5, BP 6, Insurance 6, Accessories 1, Cost 3. KPI names, values, actuals, opportunity and comparison references are retained in English.</span></div><div><b>02</b><span><strong>Monday Store Manager Dashboard / supplied HTML</strong>Dealer briefing, service results, alerts, peer comparisons, inspection 420 → replacement need 82 → quotation 54 → sale 18, and four weekly actions.</span></div><div><b>03</b><span><strong>VC PDF</strong>p.1 / p.6 absorption roadmap; p.2 GS guidelines; p.3 BP and T.CARE; p.4 core KPI set; p.5 capacity and core-to-process logic; p.7–8 the GS process tree.</span></div><div><b>04</b><span><strong>GS process tree</strong>UIO, CPUS and CRT by age; Periodic Maintenance; Other appointment / walk-in; TCFR+; Smart Plan 3 / 5 / 10; PM Appointment; Call out / Call in / Online; Eco Pack; Additional Jobs; Tire Penetration. The tire quotation stages are completed with the Monday HTML funnel.</span></div></div><div class="drawer-callout">The PDF and HTML use different reference levels in places. BP workbay utilization, for example, is compared with 80% in the HTML and has a 100% Criterion in PDF p.3. Both are shown explicitly.</div><p class="note">Sample settings: fictional dealers, time series, source-class assignments, supplementary level thresholds, process node values and scenario sensitivities. Monetary examples use THB; they are not currency conversions. Original internal documents are not included in this website.</p>`)}
const TOUR=[['A stronger Monday.','See last week’s results and this week’s next move.'],['The agreed 21 core KPIs.','Open the evidence. Compare references. Complete a missing input.'],['Follow the operating process.','From UIO and CPUS to appointments, quotations and conversion.'],['Change a lever. Compare two ideas.','Try an opportunity, save a scenario and turn it into a commitment.'],['Learn across the dealer network.','Filter comparable dealers and inspect the practices behind the gap.'],['A path toward ninety.','Connect operating improvements to fixed-cost coverage.'],['Make the next step visible.','Assign an owner and a due date. Track the commitment through completion.']];
function openGuide(){openDrawer(`<p class="eyebrow">TMT VC COMMAND / PRESENTATION</p><h2>The dealer growth story.<br>In 60 seconds.</h2><div class="guide-list">${TOUR.map((v,i)=>`<div><b>0${i+1}</b><span><strong>${v[0]}</strong>${v[1]}</span></div>`).join('')}</div><div class="drawer-callout">Enter full screen and start the presentation. Pause at any point to explore a KPI or change a scenario.</div><div class="key-line"><kbd>1</kbd>–<kbd>7</kbd> Switch view</div><div class="key-line"><kbd>Space</kbd> Pause / resume tour</div><div class="key-line"><kbd>←</kbd><kbd>→</kbd> Previous / next scene</div><div class="key-line"><kbd>Esc</kbd> Close details / end tour</div><button class="gold-button full-width" id="guideStart">Start presentation ${icon('play')}</button>`);$('#guideStart').onclick=()=>{closeDrawer();startTour()}}
function clearTourAuto(){tourAutoTimers.forEach(clearTimeout);tourAutoTimers=[]}
function startTour(){closeDrawer();state.tour=true;state.tourPaused=false;state.tourStep=0;state.tourElapsed=0;$('#tourBar').hidden=false;$('#tourPause').textContent='Ⅱ';$('#tourPause').setAttribute('aria-label','Pause tour');document.body.classList.add('touring');clearInterval(tourTimer);tourScene(0);tourTimer=setInterval(()=>{if(!state.tour||state.tourPaused||document.hidden)return;state.tourElapsed+=100;$('#tourProgress').style.width=state.tourElapsed/85+'%';if(state.tourElapsed>=8500){if(state.tourStep>=6){endTour();toast('Presentation complete. Explore any view.')}else tourScene(state.tourStep+1)}},100)}
function tourScene(i){clearTourAuto();state.tourStep=Math.max(0,Math.min(6,i));state.tourElapsed=0;if(state.tourStep===1)Object.assign(state,{category:'ALL',status:'all',layout:'compact'});if(state.tourStep===2){state.treeMode='gs-process';treeSelection='gs-process'}if(state.tourStep===3)state.driver='tire';setView(VIEWS[state.tourStep]);$('#tourStep').textContent='0'+(state.tourStep+1)+' / 07';$('#tourTitle').textContent=TOUR[state.tourStep][0];$('#tourCaption').textContent=TOUR[state.tourStep][1];$('#tourProgress').style.width='0%';$('#tourPrev').disabled=state.tourStep===0;$('#tourNext').disabled=state.tourStep===6;if(!state.tourPaused&&state.tourStep===2)tourAutoTimers.push(setTimeout(()=>{if(state.view==='tree'&&!state.tourPaused){revealTree('tire-quotation');renderTreeCanvas(true)}},1800));if(!state.tourPaused&&state.tourStep===3)tourAutoTimers.push(setTimeout(()=>{if(state.view==='drivers'&&!state.tourPaused){labValues={proposal:100,close:50};$('#proposalSlider').value=100;$('#closeSlider').value=50;updateLab()}},1800));if(!state.tourPaused&&state.tourStep===5)tourAutoTimers.push(setTimeout(()=>{if(state.view==='vc'&&!state.tourPaused){Object.assign(state,{tires:15,bay:65,cost:6,year:2028});$('#tireSlider').value=15;$('#baySlider').value=65;$('#costSlider').value=6;$('#yearSlider').value=2028;updateScenario()}},1800))}
function pauseTour(force){state.tourPaused=force??!state.tourPaused;$('#tourPause').textContent=state.tourPaused?'▷':'Ⅱ';$('#tourPause').setAttribute('aria-label',state.tourPaused?'Resume tour':'Pause tour');if(state.tourPaused)clearTourAuto()}
function endTour(){state.tour=false;clearInterval(tourTimer);clearTourAuto();$('#tourBar').hidden=true;document.body.classList.remove('touring')}
function changeStore(id){saveActions();state.store=id;state.actions=getActions();$('#storeSelect').value=id;setView(state.view,{scroll:false});toast('Workspace switched to '+storeInfo().name)}
function bindGlobal(){document.addEventListener('click',e=>{const el=e.target;const nav=el.closest('[data-view]');if(nav){if(state.tour)endTour();setView(nav.dataset.view);return}const detail=el.closest('[data-detail]');if(detail){openKpi(detail.dataset.detail);return}const driver=el.closest('[data-driver]');if(driver){if(state.tour)endTour();closeDrawer();state.driver=driver.dataset.driver;setView('drivers');return}const group=el.closest('[data-open-group]');if(group){Object.assign(state,{category:group.dataset.openGroup,status:'all'});setView('matrix');return}const dealer=el.closest('[data-dealer]');if(dealer){openDealer(dealer.dataset.dealer);return}const pg=el.closest('[data-page]');if(pg){state.page+=+pg.dataset.page;$('#dealerTable').innerHTML=renderDealerTable();return}const exp=el.closest('[data-tree-expand]');if(exp){const id=exp.dataset.treeExpand;if(treeOpen.has(id))treeOpen.delete(id);else treeOpen.add(id);treeSelection=id;renderTreeCanvas();return}const sel=el.closest('[data-tree-select]');if(sel){treeSelection=sel.dataset.treeSelect;renderTreeCanvas();return}const jump=el.closest('[data-tree-jump]');if(jump){revealTree(jump.dataset.treeJump);setView('tree');renderTreeCanvas(true);return}const move=el.closest('[data-move]');if(move){const a=state.actions.find(a=>a.id===move.dataset.move);a.status={todo:'doing',doing:'done',done:'todo'}[a.status];saveActions();setView('actions',{scroll:false});return}const edit=el.closest('[data-edit-action]');if(edit){editAction(edit.dataset.editAction);return}if(el.closest('[data-funnel]')){state.driver='tire';setView('drivers');return}if(el.closest('[data-info="sources"]'))openSourceNotes();if(el.closest('[data-action="tour"]'))startTour()});$('#storeSelect').onchange=e=>changeStore(e.target.value);$('#periodSelect').onchange=e=>{state.period=e.target.value;setView(state.view,{scroll:false});toast('Reporting week updated')};$('#motionButton').onclick=toggleMotion;$('#fullscreenButton').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Use the browser full-screen control')}catch{toast('Use the browser full-screen control')}};document.addEventListener('fullscreenchange',()=>$('#fullscreenButton').setAttribute('aria-label',document.fullscreenElement?'Exit full screen':'Enter full screen'));$('#guideButton').onclick=openGuide;$('#tourButton').onclick=startTour;$('#drawerClose').onclick=closeDrawer;$('#drawerBackdrop').onclick=closeDrawer;$('#tourPrev').onclick=()=>tourScene(state.tourStep-1);$('#tourNext').onclick=()=>tourScene(state.tourStep+1);$('#tourPause').onclick=()=>pauseTour();$('#tourEnd').onclick=endTour;window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(VIEWS.includes(v)){if(state.tour)endTour();setView(v)}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#detailDrawer').hidden)closeDrawer();else if(state.tour)endTour();return}if(!$('#detailDrawer').hidden){if(e.key==='Tab'){const a=$$('button:not(:disabled),a,input,select,textarea,[tabindex="0"]',$('#detailDrawer')),first=a[0],last=a.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}if(/^(INPUT|SELECT|TEXTAREA)$/.test(document.activeElement?.tagName))return;if(['Enter',' '].includes(e.key)&&document.activeElement?.matches('[data-tree-select],[data-tree-expand]')){e.preventDefault();document.activeElement.dispatchEvent(new MouseEvent('click',{bubbles:true}));return}if(state.tour&&[' ','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();if(e.key===' ')pauseTour();else tourScene(state.tourStep+(e.key==='ArrowRight'?1:-1));return}if(/^[1-7]$/.test(e.key)){if(state.tour)endTour();setView(VIEWS[+e.key-1])}})}
function init(){initEffects();hydrate();chartDefaults();bindGlobal();document.body.classList.toggle('motion-off',!state.motion);if(!state.motion)$('#motionButton').setAttribute('aria-label','Resume motion');setView(location.hash.slice(1)||'overview');setTimeout(()=>$('#intro')?.remove(),1900);if(new URLSearchParams(location.search).get('present')==='1')setTimeout(startTour,2000)}
init();
